#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<int>a(n),s;
for(int i=0;i<n;++i){scanf("%d",&a[i]);s.push_back(a[i]);}
sort(s.begin(),s.end());
int c=0;for(int i=0;i<n;++i)if(a[i]!=s[i])++c;
printf("%d\n",c);return 0;}

